class Solution {
public:
    vector<int> minSubsequence(vector<int>& nums) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }

        int count[101] = {0};
        for (int num : nums) {
            count[num]++;
        }

        vector<int> result;
        int sub_sum = 0;

        for (int val = 100; val >= 1; val--) {
            while (count[val] > 0 && sub_sum * 2 <= total) {
                result.push_back(val);
                sub_sum += val;
                count[val]--;
            }
        }

        return result;
    }
};
